"""Complete 24 original psychotic-disorder questions."""
from create_psych_psychosis_diagnosis import rows,q,PS,AN,CT,ref
from qbank_authoring import finalize
CL=ref('Current clozapine prescribing information','https://www.dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=883b5d43-0339-7dc1-f775-93791fb9b978&type=display')

q('For a first episode of schizophrenia-spectrum psychosis, which treatment plan is most appropriate?', 'Shared selection of an oral antipsychotic with psychological and family interventions and early-intervention support',[
 ('Routine long-term combination of two antipsychotics at initiation','Routine antipsychotic polypharmacy is not the preferred starting strategy.'),('Medication without any physical-health or functional assessment','Treatment should include monitoring and recovery needs.'),('Delay all treatment until a six-month diagnostic threshold is reached','Early treatment should not wait for a final longitudinal label.')],
 'Treat early and broadly','**Medication and psychosocial care address complementary needs.**',['Discuss adverse-effect profiles and the patient’s priorities.','Assess medical causes, substances and immediate risk.'],'**Use a defined treatment trial with response and safety review.**',['Monitor weight, metabolic health, movement effects and functioning.','Support education, work and family participation.'],[['Medication','Shared choice and monitored trial'],['Psychological','CBT/family work'],['Recovery','Function and physical health']],[PS],style='clinical_scenario')

q('A patient has persistent schizophrenia symptoms despite two adequate sequential antipsychotic trials, with adherence and diagnosis confirmed. Which next treatment is indicated for consideration?', 'Clozapine',[
 ('A third routine nonclozapine trial is always required first','Guidelines support clozapine after the defined two adequate failures.'),('Routine addition of a second nonclozapine antipsychotic as the preferred evidence-based step','This should not displace indicated clozapine assessment.'),('A benzodiazepine as a substitute for antipsychotic treatment of persistent psychosis','It does not address treatment-resistant core psychotic symptoms.')],
 'Recognize treatment resistance without unnecessary delay','**Clozapine has a specific role in treatment-resistant schizophrenia.**',['Adequacy includes dose, duration, adherence and tolerability context.','Review substance use and alternative diagnoses.'],'**Discuss benefits and the required safety system.**',['Assess blood counts, cardiac and bowel risks and other baseline factors.','Use gradual titration and ongoing monitoring.'],[['Threshold','Two adequate sequential failures'],['Before labeling','Confirm exposure and diagnosis'],['Next option','Clozapine']],[PS,AN],style='clinical_scenario')

q('Before labeling persistent psychosis as treatment-resistant, which issue is essential to exclude?', 'Inadequate medication exposure from nonadherence, insufficient dose/duration or interacting factors',[
 ('Any residual social disability as proof that all medications have failed','Disability can have multiple causes beyond active psychosis.'),('A normal blood count as proof of an adequate antipsychotic trial','It does not establish drug exposure or efficacy.'),('Absence of acute agitation as proof that delusions are fully treated','Behavioral calm does not equal resolution of psychosis.')],
 'Apparent resistance can be pseudo-resistance','**A prescription is not the same as an adequate completed trial.**',['Review the actual treatment history and barriers.','Substances, interactions and incorrect diagnosis can explain poor response.'],'**Address the identified barrier and document a meaningful trial.**',['Use drug levels when clinically informative.','Discuss adherence respectfully rather than treating it as misconduct.'],[['Dose/duration','Adequacy'],['Adherence','Actual exposure'],['Other factors','Substances/interactions/diagnosis']],[PS,AN])

q('A patient responds to oral antipsychotic treatment but repeatedly relapses after unintentionally missing doses and prefers less frequent dosing. Which option is appropriate?', 'Discuss a suitable long-acting injectable antipsychotic',[
 ('Label the illness treatment-resistant without addressing missed exposure','Response during treatment argues for an adherence/access issue.'),('Use routine double-dose oral treatment only on clinic days','This is not a safe substitute for a validated regimen.'),('Offer clozapine solely because the oral prescription was not taken consistently','Clozapine is not the automatic response to this pattern.')],
 'Match delivery to the person’s needs','**An LAI can reduce the burden of daily dosing and clarify medication exposure.**',['It should be a shared choice rather than a punishment.','Tolerability, preparation-specific initiation and follow-up requirements matter.'],'**Address practical barriers alongside the formulation change.**',['Review side effects, cost, access and beliefs about treatment.','Continue psychosocial and physical-health care.'],[['Pattern','Relapse after missed doses'],['Potential option','LAI'],['Decision','Shared and preparation-specific']],[PS],style='clinical_scenario')

q('Following the FDA removal of the US clozapine REMS in June 2025, which statement is correct?', 'Removal of the REMS reporting/access program did not eliminate severe-neutropenia risk or recommended ANC monitoring',[
 ('ANC monitoring is no longer clinically relevant','The risk remains and prescribing-information monitoring is still recommended.'),('The drug became free of all boxed-warning risks','Regulatory administrative changes do not remove biological adverse effects.'),('The US change automatically replaced every country’s monitoring rules','Local regulatory and product requirements differ.')],
 'Separate an administrative program from clinical safety','**The FDA removed the REMS requirement while retaining monitoring recommendations.**',['Use the current product label and local requirements.','Counsel about fever and infection symptoms.'],'**Maintain an effective blood-count and adverse-effect follow-up plan.**',['Interpret low counts using the appropriate patient context and protocol.','Do not extrapolate US access rules globally.'],[['Changed','US REMS program'],['Unchanged risk','Severe neutropenia'],['Care','ANC monitoring per current guidance']],[ref('FDA clozapine REMS removal safety communication','https://www.fda.gov/drugs/drug-safety-communications/fda-removes-risk-evaluation-and-mitigation-strategy-rems-program-antipsychotic-drug-clozapine')])

q('During early clozapine titration, a patient develops persistent tachycardia, fever, chest discomfort and elevated troponin. Which complication requires urgent assessment?', 'Clozapine-associated myocarditis',[
 ('Benign tachycardia established without further testing','The symptoms and myocardial-injury marker require urgent evaluation.'),('Tardive dyskinesia','This does not explain the inflammatory/cardiac syndrome.'),('Uncomplicated constipation as the complete explanation','Bowel effects do not account for this pattern.')],
 'Do not dismiss every early adverse effect as expected titration','**Myocarditis can occur early in clozapine treatment.**',['Evaluate other causes of myocardial injury and infection as appropriate.','Severity can progress rapidly.'],'**Arrange urgent medical/cardiac assessment and manage clozapine according to the suspected reaction.**',['Monitor hemodynamics and cardiac function.','Rechallenge decisions require specialist risk assessment rather than automatic resumption.'],[['Timing','Often early'],['Clues','Symptoms plus troponin/inflammatory findings'],['Action','Urgent evaluation']],[CL],style='clinical_scenario')

q('A clozapine-treated patient has several days without a bowel movement, abdominal distension, pain and vomiting. What is the appropriate response?', 'Urgent assessment for gastrointestinal hypomotility, ileus or obstruction',[
 ('Reassure because constipation is always a minor nuisance','Severe bowel complications can be fatal.'),('Add an antimuscarinic for the abdominal symptoms without assessment','This can worsen hypomotility.'),('Wait for neutropenia before considering a clozapine adverse effect','GI toxicity is independent of the blood-count complication.')],
 'Bowel monitoring is part of clozapine safety','**Hypomotility can progress to impaction, obstruction, ischemia or perforation.**',['Patient-reported stool frequency alone may understate severity.','Review other constipating drugs and hydration.'],'**Escalate red-flag symptoms promptly.**',['Use a prevention/treatment bowel regimen when appropriate.','Do not give routine oral laxatives blindly when obstruction is suspected.'],[['Common beginning','Constipation'],['Red flags','Pain/distension/vomiting'],['Risk','Serious bowel injury']],[ref('FDA clozapine serious bowel complication warning','https://www.fda.gov/drugs/drug-safety-communications/fda-strengthens-warning-untreated-constipation-caused-schizophrenia-medicine-clozapine-clozaril-can')],style='clinical_scenario')

q('A stable clozapine patient stops cigarette smoking during admission and becomes more sedated without a dose change. Which mechanism should be considered?', 'Loss of smoke-related CYP1A2 induction can raise clozapine exposure',[
 ('Nicotine replacement necessarily reproduces the same enzyme induction','The relevant induction is largely due to combustion products rather than nicotine itself.'),('Smoking cessation reliably lowers clozapine levels','The expected direction is often the opposite.'),('The unchanged prescribed dose excludes pharmacokinetic toxicity','Clearance can change without a dose change.')],
 'A change in smoking can be a drug-interaction event','**Stopping tobacco smoke exposure can reduce clozapine metabolism.**',['Infection/inflammation can also raise exposure.','The size and timing of the change vary.'],'**Review symptoms, dose and drug levels with the prescribing team.**',['Plan monitoring when smoking stops or restarts.','Do not discourage cessation; adapt medication safely.'],[['Smoking','Enzyme induction'],['Cessation','Exposure may rise'],['Nicotine replacement','Not equivalent to smoke induction']],[CL],style='clinical_scenario')

q('Which antipsychotic among these options has a particularly important weight-gain and metabolic-risk burden?', 'Olanzapine',[
 ('Aripiprazole','It generally has a lower metabolic burden, although risk is not absent.'),('Lurasidone','It generally has a more favorable metabolic profile than olanzapine.'),('Ziprasidone','Its other risks require attention, but major weight gain is generally less prominent.')],
 'Antipsychotic choice includes physical-health trade-offs','**Metabolic effects differ substantially among agents.**',['Weight, blood pressure, glucose and lipids need monitoring.','Past response and other adverse effects also influence choice.'],'**Prevent and treat metabolic disease rather than merely recording weight.**',['Use lifestyle and indicated medical interventions.','Discuss a switch only after balancing relapse risk and alternatives.'],[['Olanzapine','Higher metabolic burden'],['Monitoring','Weight/glucose/lipids/BP'],['Choice','Benefit-risk rather than one adverse effect alone']],[PS,AN])

q('Two days after haloperidol is started, a young adult develops painful neck spasm and upward deviation of the eyes. Which diagnosis and treatment fit?', 'Acute dystonia; give an appropriate parenteral anticholinergic or antihistaminic treatment',[
 ('Tardive dyskinesia; increase haloperidol as the definitive response','The acute timing and sustained spasm favor dystonia, and more blockade can worsen it.'),('Akathisia; treat only as anxiety','Akathisia is an inner restlessness syndrome rather than sustained ocular/neck spasm.'),('Neuroleptic malignant syndrome established without fever or systemic findings','NMS has a broader systemic syndrome.')],
 'Recognize an acute extrapyramidal reaction','**Dystonia can involve the neck, jaw, eyes and occasionally airway muscles.**',['Young age and potent D2 blockade increase risk.','Airway symptoms require immediate emergency assessment.'],'**Treat promptly and review the antipsychotic plan.**',['Provide a short prevention strategy if appropriate after the acute reversal.','Explain the reaction and recurrence precautions.'],[['Timing','Hours to days'],['Pattern','Sustained painful contractions'],['Treatment','Prompt specific reversal']],[AN],style='clinical_scenario')

q('After an antipsychotic dose increase, a patient cannot sit still, repeatedly paces and describes unbearable inner restlessness. Which diagnosis is most likely?', 'Akathisia',[
 ('Worsening psychotic agitation established by pacing alone','The subjective restlessness and dose relationship suggest a medication effect.'),('Parkinsonism','Bradykinesia and rigidity are different motor features.'),('Tardive dyskinesia','This usually involves involuntary repetitive movements rather than the characteristic urge to move.')],
 'Ask about subjective restlessness before escalating the drug','**Akathisia can be profoundly distressing and mistaken for illness progression.**',['Dose and agent are important contributors.','Assess safety and the effect on adherence.'],'**Review dose/switch options and appropriate symptom treatment.**',['A beta blocker or other selected treatment may help after contraindication assessment.','Do not respond automatically with more dopamine blockade.'],[['Subjective','Inner restlessness'],['Objective','Pacing/inability to sit'],['Key risk','Misdiagnosis as agitation']],[AN],style='clinical_scenario')

q('A patient with a compatible catatonic syndrome has no immediate airway instability. Which is an appropriate initial specific diagnostic-treatment step under monitored care?', 'A lorazepam challenge with structured reassessment of catatonic signs',[
 ('Escalate antipsychotic treatment automatically before evaluating catatonia','Dopamine blockade can worsen selected catatonic states.'),('Treat immobility as voluntary refusal and withhold supportive care','Catatonia is a medical syndrome with serious complications.'),('Use a negative response to one challenge as absolute exclusion of catatonia','Sensitivity is imperfect and further assessment may be needed.')],
 'A challenge can support diagnosis and begin treatment','**Benzodiazepines are a first-line catatonia treatment pathway.**',['Monitor sedation and breathing, particularly with medical illness or other sedatives.','Investigate psychiatric, neurological and systemic causes.'],'**Escalate to ECT when indicated by severity or inadequate response.**',['Provide hydration, nutrition, thrombosis and pressure-injury prevention.','Malignant features require urgent intensive multidisciplinary management.'],[['Challenge','Lorazepam'],['Assessment','Objective symptom change'],['Further treatment','Cause-directed care and selected ECT']],[CT],style='clinical_scenario')

if __name__=='__main__':finalize('Psychiatry',2,'Psychotic Disorders','psych-psychosis',rows,24)
